// World textures (PNG files generated by tools/gen_textures.py) and procedural sprites.
import * as THREE from '../lib/three.module.js';

const TEX_DIR = 'assets/textures/';

// Trilinear + anisotropic filtering: sharp up close, no shimmering in the distance.
function setupFiltering(t, anisotropy) {
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.anisotropy = anisotropy;
  return t;
}

function loadTexture(loader, name, anisotropy) {
  return setupFiltering(loader.load(TEX_DIR + name), anisotropy);
}

function canvasTexture(w, h, draw, anisotropy = 1) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.anisotropy = anisotropy;
  return t;
}

// ---------- imp sprite, 128x128, drawn in a 32-unit space ----------

const IMP = {
  skin: '#9a4524', skinLight: '#d07a44', skinDark: '#5a2210',
  horn: '#efe3c0', hornDark: '#8a7a58', claw: '#f4ead2',
  eye: '#ffe14a', mouth: '#1c0404', blood: '#6e0806'
};

function ellipse(g, x, y, rx, ry, fill) {
  g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); g.fillStyle = fill; g.fill();
}

function radial(g, x, y, r, inner, outer) {
  const gr = g.createRadialGradient(x - r * 0.3, y - r * 0.35, r * 0.1, x, y, r);
  gr.addColorStop(0, inner); gr.addColorStop(1, outer);
  return gr;
}

// Limb as a tapered capsule from (x1,y1) to (x2,y2).
function limb(g, x1, y1, x2, y2, w1, w2, fill) {
  const a = Math.atan2(y2 - y1, x2 - x1), nx = -Math.sin(a), ny = Math.cos(a);
  g.beginPath();
  g.moveTo(x1 + nx * w1, y1 + ny * w1);
  g.lineTo(x2 + nx * w2, y2 + ny * w2);
  g.arc(x2, y2, w2, a + Math.PI / 2, a - Math.PI / 2, true);
  g.lineTo(x1 - nx * w1, y1 - ny * w1);
  g.arc(x1, y1, w1, a - Math.PI / 2, a + Math.PI / 2, true);
  g.fillStyle = fill; g.fill();
}

function claws(g, x, y, dir) {
  g.fillStyle = IMP.claw;
  for (let i = -1; i <= 1; i++) {
    g.beginPath();
    g.moveTo(x + i * 1.1 - 0.5, y);
    g.lineTo(x + i * 1.4 + dir * 0.4, y + dir * 2.2);
    g.lineTo(x + i * 1.1 + 0.5, y);
    g.fill();
  }
}

function horn(g, x, y, side) {
  const gr = g.createLinearGradient(x, y + 3, x + side * 3, y - 4);
  gr.addColorStop(0, IMP.hornDark); gr.addColorStop(1, IMP.horn);
  g.beginPath();
  g.moveTo(x - side * 1.2, y + 1.5);
  g.quadraticCurveTo(x + side * 1.5, y - 1, x + side * 2.6, y - 4.6);
  g.quadraticCurveTo(x + side * 0.4, y - 1.6, x + side * 1.3, y + 1.6);
  g.closePath();
  g.fillStyle = gr; g.fill();
}

function drawImp(g, frame) {
  g.save();
  g.scale(4, 4);

  if (frame === 'dead') {
    ellipse(g, 16, 29.5, 13, 2.4, IMP.blood);
    ellipse(g, 16, 27, 10, 3.4, radial(g, 16, 27, 10, IMP.skinLight, IMP.skinDark));
    ellipse(g, 7, 26.5, 3.4, 2.6, radial(g, 7, 26.5, 3.4, IMP.skinLight, IMP.skin));
    horn(g, 5, 25.5, -1);
    limb(g, 20, 27, 28, 28.5, 1.4, 1, IMP.skinDark);
    g.restore();
    return;
  }

  const attack = frame === 'attack';
  const stepA = frame === 'walk1' ? 1.2 : frame === 'walk2' ? -1.2 : 0;

  // legs
  limb(g, 12.5, 20, 11.5 + stepA, 30.5, 2.1, 1.5, IMP.skinDark);
  limb(g, 19.5, 20, 20.5 - stepA, 30.5, 2.1, 1.5, IMP.skinDark);
  claws(g, 11.5 + stepA, 30.6, 1);
  claws(g, 20.5 - stepA, 30.6, 1);

  // arms behind the torso when raised
  if (attack) {
    limb(g, 10, 13, 5, 5, 1.9, 1.4, IMP.skin);
    limb(g, 22, 13, 27, 5, 1.9, 1.4, IMP.skin);
    claws(g, 5, 4.4, -1);
    claws(g, 27, 4.4, -1);
    // fireball forming between the hands
    const fg = g.createRadialGradient(16, 3.4, 0.2, 16, 3.4, 4.4);
    fg.addColorStop(0, 'rgba(255,250,210,1)'); fg.addColorStop(0.4, 'rgba(255,180,40,0.95)'); fg.addColorStop(1, 'rgba(255,60,0,0)');
    g.fillStyle = fg; g.fillRect(10, -2, 12, 11);
  }

  // torso
  ellipse(g, 16, 16, 7.6, 7.2, radial(g, 16, 16, 8, IMP.skinLight, IMP.skinDark));
  g.strokeStyle = 'rgba(60,20,8,0.55)'; g.lineWidth = 0.45;
  for (const yy of [14.5, 16.8, 19]) { g.beginPath(); g.moveTo(12.6, yy); g.quadraticCurveTo(16, yy + 0.9, 19.4, yy); g.stroke(); }

  if (!attack) {
    limb(g, 9.6, 12.5, 6.4, 21, 2, 1.5, IMP.skin);
    limb(g, 22.4, 12.5, 25.6, 21, 2, 1.5, IMP.skin);
    claws(g, 6.4, 21.8, 1);
    claws(g, 25.6, 21.8, 1);
  }

  // head
  horn(g, 12.4, 5.5, -1);
  horn(g, 19.6, 5.5, 1);
  ellipse(g, 16, 7.2, 4.8, 4.4, radial(g, 16, 7.2, 5, IMP.skinLight, IMP.skin));
  // brow ridge
  g.fillStyle = IMP.skinDark;
  g.beginPath(); g.moveTo(12, 5.8); g.quadraticCurveTo(16, 7.4, 20, 5.8); g.lineTo(20, 6.6); g.quadraticCurveTo(16, 8, 12, 6.6); g.fill();
  // glowing eyes
  g.save();
  g.shadowColor = IMP.eye; g.shadowBlur = 3;
  ellipse(g, 14.2, 7.3, 1, 0.7, IMP.eye);
  ellipse(g, 17.8, 7.3, 1, 0.7, IMP.eye);
  g.restore();
  // mouth
  if (attack) {
    ellipse(g, 16, 10, 2.2, 1.4, IMP.mouth);
    g.fillStyle = IMP.claw;
    g.beginPath(); g.moveTo(14.4, 9); g.lineTo(14.9, 10.2); g.lineTo(15.3, 9); g.fill();
    g.beginPath(); g.moveTo(16.7, 9); g.lineTo(17.1, 10.2); g.lineTo(17.6, 9); g.fill();
  } else {
    g.strokeStyle = IMP.mouth; g.lineWidth = 0.6;
    g.beginPath(); g.moveTo(14.2, 9.8); g.quadraticCurveTo(16, 10.6, 17.8, 9.8); g.stroke();
  }

  if (frame === 'pain') {
    g.globalCompositeOperation = 'source-atop';
    g.fillStyle = 'rgba(255,255,255,0.55)';
    g.fillRect(0, 0, 32, 32);
  }
  g.restore();
}

export function createTextures(renderer) {
  const anisotropy = renderer.capabilities.getMaxAnisotropy();
  const loader = new THREE.TextureLoader();

  const ground = loadTexture(loader, 'ground_albedo.png', anisotropy);
  const groundNormal = loadTexture(loader, 'ground_normal.png', anisotropy);
  ground.repeat.set(40, 40);
  groundNormal.repeat.set(40, 40);

  const wall = loadTexture(loader, 'bricks_albedo.png', anisotropy);
  const wallNormal = loadTexture(loader, 'bricks_normal.png', anisotropy);

  const imp = {};
  for (const f of ['walk1', 'walk2', 'attack', 'pain', 'dead']) imp[f] = canvasTexture(128, 128, g => drawImp(g, f));

  // soft round particle
  const dot = canvasTexture(32, 32, g => {
    const gr = g.createRadialGradient(16, 16, 0, 16, 16, 16);
    gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(0.5, 'rgba(255,255,255,0.8)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 32, 32);
  });

  const fire = canvasTexture(64, 64, g => {
    const gr = g.createRadialGradient(32, 32, 2, 32, 32, 30);
    gr.addColorStop(0, '#fffbe0'); gr.addColorStop(0.3, '#ffd040');
    gr.addColorStop(0.65, '#ff5a10'); gr.addColorStop(1, 'rgba(120,10,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
  });

  return { ground, groundNormal, wall, wallNormal, imp, dot, fire };
}
